#include <bits/stdc++.h>
using namespace std;
const int B=1e6, M=998244353, mod=1e9+7;
typedef long long ll;
ll n, totalCount1, totalCount2;
int sumArray[10], result;
vector<int> digitValues[10];

void buildValues(int depth, ll val) {
    if (depth > 6) return;
    int w = (++totalCount1) - val + M;
    digitValues[depth].push_back(w);
    sumArray[depth] = (sumArray[depth] + w) % mod;
    for (int digit=0; digit<=9; ++digit) {
        buildValues(depth+1, val*10+digit);
    }
}

void traverse(ll v) {
    if (v > n) return;
    if (v < n/B && 10*v > n/B) {
        for (int i=0, p=1; i<=6; ++i, p*=10) {
            int w = (totalCount2 + (ll)(M - p) * v + M) % M;
            int c = (int)(digitValues[i].end() - lower_bound(digitValues[i].begin(), digitValues[i].end(), M - w));
            result = (result + (ll)digitValues[i].size() * w + sumArray[i] + (ll)(mod - M) * c) % mod;
        }
        totalCount2 += totalCount1;
        return;
    }
    ++totalCount2;
    result = (result + (totalCount2 - v % M + M) % M) % mod;
    for (int digit=0; digit<=9; ++digit) {
        traverse(v*10+digit);
    }
}

int main() {
    cin >> n;
    buildValues(0, 0);
    for (int i=0; i<=6; ++i) {
        sort(digitValues[i].begin(), digitValues[i].end());
    }
    for (int i=1; i<=9; ++i) {
        traverse(i);
    }
    cout << result << endl;
    return 0;
}
